use lan_mouse_adapter_api::{read_messages,write_message,Capabilities,Completion,CopyManifest,EntryKind,Message,Progress,SourceEntry,GNOME_COPIED_FILES_MIME,PROTOCOL_VERSION,URI_LIST_MIME};
use std::io::{self,BufReader,BufWriter};use std::process::Command;
fn parse(m:&str,v:&str,id:String)->Option<CopyManifest>{if m!=URI_LIST_MIME&&m!=GNOME_COPIED_FILES_MIME{return None}let mut l=v.lines().filter(|x|!x.trim().is_empty());let op=if m==GNOME_COPIED_FILES_MIME{match l.next()?.trim(){"copy"=>lan_mouse_adapter_api::Operation::Copy,"cut"=>lan_mouse_adapter_api::Operation::Move,_=>return None}}else{lan_mouse_adapter_api::Operation::Copy};let mut entries=Vec::new();for raw in l{let uri=raw.trim();if uri.starts_with('#'){continue}if !uri.contains("://")||uri.starts_with('-'){return None}entries.push(SourceEntry{uri:uri.into(),kind:EntryKind::Other,size:None})}if entries.is_empty(){return None}Some(CopyManifest{transfer_id:id,operation:op,entries})}
fn transfer(m:&CopyManifest,d:&str,out:&mut BufWriter<io::Stdout>)->io::Result<bool>{if d.is_empty()||d.starts_with('-'){return Ok(false)}let a=match m.operation{lan_mouse_adapter_api::Operation::Copy=>"copy",lan_mouse_adapter_api::Operation::Move=>"move"};for(i,e)in m.entries.iter().enumerate(){let status=match Command::new("gio").args([a,"--",&e.uri,d]).status(){Ok(s)=>s,Err(_)=>return Ok(false)};if !status.success(){return Ok(false)}write_message(out,&Message::Progress(Progress{transfer_id:m.transfer_id.clone(),completed_entries:(i+1)as u64,total_entries:m.entries.len()as u64,completed_bytes:None,total_bytes:None})).map_err(|e|io::Error::other(e.to_string()))?}Ok(true)}
fn main()->io::Result<()>{let mut out=BufWriter::new(io::stdout());write_message(&mut out,&Message::Hello{protocol_version:PROTOCOL_VERSION,adapter_id:"gio".into(),name:"GIO/Nautilus".into(),capabilities:Capabilities{clipboard_read:true,paste:true,cancel:true,requires_live_mount:false,mime_types:vec![URI_LIST_MIME.into(),GNOME_COPIED_FILES_MIME.into()]}}).map_err(|e|io::Error::other(e.to_string()))?;let mut m=None;for x in read_messages(BufReader::new(io::stdin())){match x.map_err(|e|io::Error::other(e.to_string()))?{Message::ClipboardData{transfer_id,mime_type,value}=>if let Some(v)=parse(&mime_type,&value,transfer_id){write_message(&mut out,&Message::CopyManifest(v.clone())).ok();m=Some(v)},Message::PasteDestination(d)=>if let Some(v)=m.take(){let ok=d.transfer_id==v.transfer_id&&transfer(&v,&d.destination_uri,&mut out)?;write_message(&mut out,&Message::Completed(Completion{transfer_id:v.transfer_id,success:ok,error:(!ok).then_some("gio transfer failed".into())})).ok()},Message::Cancel{transfer_id}=>{write_message(&mut out,&Message::Cancelled(lan_mouse_adapter_api::Cancelled{transfer_id})).ok()},_=>{}}}Ok(())}
